prog='''import numpy as np

def transform(grid):
    """Restore cells masked with color 8. The grid is 180-degree symmetric
    under (r,c) -> (N-1-r, N-1-c) with N=32 coordinates (offset-31 maps),
    and is composed of 4x4 tiles pasted at several positions with dihedral
    transforms. Masked cells are restored from symmetry partners when in
    range, otherwise from a matching 4x4 tile paste elsewhere."""
    g = np.array(grid)
    n, m = g.shape
    out = g.copy()
    mask = (g == 8)
    # 1) dihedral symmetry about center (15.5, 15.5): maps (31-r,31-c),(31-r,c),(r,31-c)
    def sym_vals(r, c):
        vals = []
        for r2, c2 in ((31-r,31-c),(31-r,c),(r,31-c)):
            if 0 <= r2 < n and 0 <= c2 < m and not mask[r2, c2]:
                vals.append(int(g[r2, c2]))
        return vals
    # 2) tile-copy search: 4x4 blocks pasted at swapped/other positions,
    #    with dihedral transforms, must agree with all visible overlap cells.
    dih = [lambda b: b, lambda b: b[::-1, :], lambda b: b[:, ::-1],
           lambda b: b[::-1, ::-1], lambda b: b.T, lambda b: b.T[::-1, :],
           lambda b: b.T[:, ::-1], lambda b: b.T[::-1, ::-1]]
    def tile_votes(r, c):
        votes = {}
        for r0 in range(n-3):
            for c0 in range(m-3):
                if mask[r0:r0+4, c0:c0+4].any():
                    continue
                B = g[r0:r0+4, c0:c0+4]
                for tf in dih:
                    Tb = np.asarray(tf(B))
                    for dr in range(-3, 4):
                        for dc in range(-3, 4):
                            r2, c2 = r - dr, c - dc
                            if not (0 <= r2 < n-3 and 0 <= c2 < m-3):
                                continue
                            ok = True
                            for i in range(4):
                                for j in range(4):
                                    R, C = r2+i, c2+j
                                    if 0 <= R < n and 0 <= C < m and not mask[R, C]:
                                        if g[R, C] != Tb[i, j]:
                                            ok = False; break
                                if not ok: break
                            if ok:
                                votes[int(Tb[r-r2, c-c2])] = votes.get(int(Tb[r-r2, c-c2]), 0)+1
        return votes
    for r in range(n):
        for c in range(m):
            if not mask[r, c]:
                continue
            vals = sym_vals(r, c)
            if len(set(vals)) == 1 and vals:
                out[r, c] = vals[0]
            else:
                votes = tile_votes(r, c)
                if votes:
                    out[r, c] = max(votes, key=votes.get)
    return out.tolist()
'''
